components.css:
.ds-card{min-width: 0;
  display: flex;
  flex-direction: column;}
.ds-card-copy{display: flex;
  flex: 1;
  flex-direction: column;
  padding-top: 18px;}
.ds-card h3{font-size: 18px;
  margin-top: 7px;
  line-height: 1.3;
  letter-spacing: -0.02em;}
.ds-category{font-size: 10px;
  color: #5a6268;
  text-transform: uppercase;
  letter-spacing: 0.06em;}
.ds-card p{font-size: 12px;
  color: #5a6268;
  margin-top: 8px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;}
.ds-card-purchase{margin-top: auto;
  padding-top: 20px;}
.ds-card-price{display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  min-height: 74px;}
.ds-price{display: flex;
  flex-direction: column;
  gap: 4px;
  font-family: var(--font-figtree), sans-serif;
  color: #171b1f;}
.ds-prefix{font-size: 12px;
  line-height: 16px;
  font-weight: 400;
  color: #5a6268;}
.ds-amount{font-size: clamp(24px, 2vw, 28px);
  line-height: 1.15;
  font-weight: 600;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;}
.ds-inquiry{padding-top: 20px;}
.ds-unit{font-size: 12px;
  line-height: 18px;
  color: #5a6268;}
.ds-stock{display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  line-height: 18px;
  margin-top: 10px;
  color: #5a6268;}
.ds-cta{display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 44px;
  margin-top: 16px;
  padding: 10px 14px;
  border: 1px solid #cbd0d3;
  border-radius: 2px;
  color: #171b1f;
  font-size: 13px;
  font-weight: 600;
  transition: background 0.2s, border-color 0.2s, color 0.2s;}
.ds-card{max-width:320px;text-decoration:none;color:#171b1f;font-family:var(--font-figtree,Figtree),sans-serif}.ds-card-media{aspect-ratio:1;display:grid;place-items:center;background:#fff;border:1px solid #eceeef;border-radius:6px;color:#5a6268;font-size:12px}.ds-card:hover .ds-cta,.ds-card:focus-visible .ds-cta{background:#d30000;border-color:#d30000;color:#fff}.ds-card:focus-visible{outline:2px solid #d30000;outline-offset:4px}.ds-card h3{font-family:var(--font-archivo,Archivo),sans-serif;font-weight:700}.ds-card p{line-height:1.65}
